//! dbt schema types of every variant and version, generated by `build.rs`.
//!
//! `build.rs` reads the upstream submodules (`build/catalog.rs` lists what
//! they hold), preprocesses each schema whose feature is on (the rules, and
//! why each exists, are in `build/preprocess.rs`) and lets typify generate
//! its module into `OUT_DIR`. `just generated` writes them out formatted.
//!
//! - `yaml::<variant>::<file>`: `yaml::latest::dbt_project`,
//!   `yaml::v1_6::dependencies`, `yaml::latest_fusion::profiles`, …
//! - `<family>::v<N>`: `run_results::v5`, `catalog::v0`, `manifest::v12`
//!   (the complete types); `manifest::projection::v<N>` the projection.
//! - A family's root re-exports its newest version: `run_results::*` is
//!   `run_results::v6::*`, and `manifest::*` is the newest projection.
//!
//! typify's output is not ours to lint (rustdoc's lints neither: its docs are
//! upstream's descriptions): through `include!` clippy would read
//! it as this crate's code, which `import_types!` kept it from.
#![allow(clippy::all, rustdoc::all)]

include!(concat!(env!("OUT_DIR"), "/index.rs"));

/// The latest YAML file schemas, where they have always been.
#[cfg(feature = "yaml-latest")]
pub use self::yaml::latest::{dbt_project, dbt_yml_files, packages, selectors};
